// Deterministic: flatten the Gmail message into the fields the pipeline needs.
const m = $json;
const from = (m.from && m.from.value && m.from.value[0]) || {};
let body = m.text || '';
if (!body && m.html) {
  body = m.html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
}
body = body.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim().slice(0, 8000);
return {
  json: {
    gmail_id: m.id,
    thread_id: m.threadId,
    message_id: m.messageId || m.id,
    from_address: (from.address || '').toLowerCase(),
    from_name: from.name || '',
    subject: (m.subject || '').slice(0, 300),
    received_at: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
    body_text: body,
  },
};

