// Deterministic checks on the LLM extraction. Never trust LLM output unchecked.
const x = $json.output;
const problems = [];
const intents = x.intents || [];
const sum = (arr, f) => (arr || []).reduce((s, e) => s + (Number(e[f]) || 0), 0);

if (!intents.length) problems.push('no intent recognised');
if (intents.includes('remittance')) {
  if (!(x.payment_amount > 0)) problems.push('remittance without a positive payment amount');
  if (!/^[A-Z]{3}$/.test(x.currency || '')) problems.push(`currency "${x.currency}" is not an ISO code`);
  if (x.value_date && isNaN(Date.parse(x.value_date))) problems.push(`value date "${x.value_date}" is invalid`);
  const refSum = sum(x.references, 'amount');
  const dedSum = sum(x.deductions, 'amount');
  if (refSum > 0 && Math.abs(refSum - dedSum - x.payment_amount) > 0.01) {
    problems.push(`quoted amounts ${refSum.toFixed(2)} minus deductions ${dedSum.toFixed(2)} != payment ${Number(x.payment_amount).toFixed(2)}`);
  }
  if (dedSum > 0 && dedSum >= x.payment_amount) problems.push('deductions exceed the payment');
}
if (intents.includes('promise_to_pay') && (!x.promise_date || isNaN(Date.parse(x.promise_date)))) {
  problems.push(`promise date "${x.promise_date}" is missing or invalid`);
}
if (!(x.references || []).length && !x.customer_name && !x.customer_number) {
  problems.push('no customer name, number or reference found');
}

const route = x.suspicious ? 'quarantine' : (problems.length ? 'manual' : 'agent');
return {
  json: {
    email_id: $('Register email').item.json.id,
    email: $('Normalize email').item.json,
    extraction: x,
    validation: { ok: problems.length === 0, problems },
    route,
  },
};

