// Deterministic gate: parse the agent's JSON, read every draft back from the S/4 mock (system of record),
// fetch invoice copies, enforce policy thresholds in code, decide the route. LLM claims are never trusted unchecked.
const MOCK = 'http://s4-ar-mock:8000';
const caseId = $('Save case').first().json.id;
const caseRef = `CASE-${caseId}`;
const raw = String($json.output || '').replace(/```(json)?/g, '').trim();

let r;
try { r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
catch (e) { r = { flags: ['NEEDS_HUMAN'], rationale: 'Agent output was not valid JSON: ' + raw.slice(0, 300) }; }
r.flags = r.flags || []; r.drafts = r.drafts || []; r.invoice_copies = r.invoice_copies || [];
r.policy_sources = r.policy_sources || []; r.reply_points = r.reply_points || [];

const verified = [], problems = [];
for (const d of r.drafts) {
  try {
    const s = await this.helpers.httpRequest({ url: `${MOCK}/drafts/${encodeURIComponent(d.draft_id)}`, json: true });
    if (s.status !== 'PENDING_APPROVAL') problems.push(`${d.draft_id}: status ${s.status}`);
    else if (s.payload.case_ref !== caseRef) problems.push(`${d.draft_id}: belongs to ${s.payload.case_ref}, not ${caseRef}`);
    else verified.push({
      draft_id: s.id, kind: s.kind, payload: s.payload,
      amount: s.payload.payment_amount ?? s.payload.disputed_amount ?? s.payload.promised_amount,
    });
  } catch (e) { problems.push(`${d.draft_id}: not found in S/4`); }
}

const copies = [];
for (const bd of r.invoice_copies) {
  try { copies.push(await this.helpers.httpRequest({ url: `${MOCK}/mock/invoice-copy/${encodeURIComponent(bd)}`, json: true })); }
  catch (e) { problems.push(`invoice copy ${bd}: not found`); }
}

// Policy thresholds enforced deterministically (01_ar_policy), not left to the LLM.
const addFlag = (f) => { if (!r.flags.includes(f)) r.flags.push(f); };
const daysAhead = (d) => Math.round((new Date(d) - new Date(new Date().toISOString().slice(0, 10))) / 86400000);
for (const v of verified) {
  if (v.kind === 'payment-advice' && v.amount > 100000) addFlag('FOUR_EYES');
  if (v.kind === 'promise-to-pay' && (daysAhead(v.payload.promised_date) > 30 || v.amount > 50000)) addFlag('CREDIT_APPROVAL');
}
if (problems.length) addFlag('NEEDS_HUMAN');

let route = 'approval';
if (r.flags.includes('SUSPICIOUS_INSTRUCTIONS')) route = 'quarantine';
else if (!verified.length || problems.length) route = 'manual';

return { json: { case_id: caseId, case_ref: caseRef, agent: r, verified_drafts: verified, invoice_copies: copies, problems, route } };

// Builds the approval email for the collector from SAP-verified data (not from the agent's own text).
const c = $('Parse & verify').first().json;
const reply = $json.text;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]));
const fmt = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const rows = c.verified_drafts.map((v) => `<tr><td>${esc(v.kind)}</td><td>${esc(v.draft_id)}</td>
  <td style="text-align:right">${fmt(v.amount)} ${esc(v.payload.currency)}</td><td>${esc(v.payload.reason_code || '')}</td>
  <td>${esc(v.payload.promised_date || '')}</td><td>${esc(v.payload.items.map((i) => i.accounting_document).join(', '))}</td></tr>`).join('');
const flags = c.agent.flags.length
  ? `<p style="color:#b00020"><b>Flags:</b> ${c.agent.flags.map(esc).join(', ')}${c.agent.flags.includes('FOUR_EYES') ? ' (second approval by AR team lead required)' : ''}</p>`
  : '<p><b>Flags:</b> none</p>';

const html = `<h3>${esc(c.case_ref)}: ${esc(c.agent.customer_name)} (${esc(c.agent.customer)}), company code 1010</h3>
${flags}
<p><b>Agent rationale:</b> ${esc(c.agent.rationale)}</p>
<table border="1" cellpadding="4" style="border-collapse:collapse">
<tr><th>Object</th><th>Draft</th><th>Amount</th><th>Reason</th><th>Date</th><th>SAP documents</th></tr>${rows}</table>
<p><b>Policy sources:</b> ${c.agent.policy_sources.map(esc).join(', ') || 'none'}</p>
<p><b>Proposed reply to the customer:</b></p>
<pre style="white-space:pre-wrap;font-family:inherit;background:#f5f5f5;padding:8px">${esc(reply)}</pre>
<p style="color:#666">Draft data above is read back from S/4 (system of record), not taken from the AI's text.
Approve = create these objects in S/4 and send the reply. Reject = discard the drafts, no reply.</p>`;

return { json: { ...c, reply_text: reply, approval_html: html,
  approval_subject: `[AR approval] ${c.case_ref} - ${c.agent.customer_name} - ${c.agent.flags.join(', ') || 'no flags'}` } };

// One item per verified draft, with the collector's decision. No decision logic in the LLM.
const c = $('Build approval message').first().json;
const approved = $input.first().json.data?.approved === true;
return c.verified_drafts.map((v) => ({
  json: { draft_id: v.draft_id, kind: v.kind, action: approved ? 'execute' : 'reject', approved, case_ref: c.case_ref },
}));
